    public record Assignment(UUID owner,String team,List<UUID> collaborators){public Assignment{if(!Set.of("PROPERTY","CABINETRY","BOARDS","GENERAL").contains(team))throw bad("TEAM_INVALID","Choose a permitted operational team.");collaborators=collaborators==null?List.of():List.copyOf(new LinkedHashSet<>(collaborators));}}public record ActivityCommand(String type,String outcome,String channel,String note){public ActivityCommand{if(!Set.of("CONTACT_ATTEMPT","HUMAN_CONTACT","NOTE","CLARIFICATION_RECEIVED","CUSTOMER_APPROVAL").contains(type))throw bad("ACTIVITY_TYPE_INVALID","Choose a supported activity type.");if(!Set.of("COMPLETED","FAILED","INFORMATION_RECEIVED","RECORDED").contains(outcome))throw bad("ACTIVITY_OUTCOME_INVALID","Choose a supported activity outcome.");if(channel!=null&&!Set.of("EMAIL","CALL","WHATSAPP","IN_PERSON","REMOTE").contains(channel))throw bad("ACTIVITY_CHANNEL_INVALID","Choose a supported activity channel.");}}public record Activity(UUID id,String type,String outcome,String channel,String note,UUID actor,Instant occurredAt){}
